typedef struct { uint8_t version; uint32_t order_id; uint16_t lines; } order_hdr_t;

size_t pack_order(uint8_t *buf, size_t cap, const order_t *o) {
    if (cap < sizeof(order_hdr_t)) return 0;
    order_hdr_t h = { .version = 3, .order_id = htonl(o->order_id),
                      .lines = htons(o->lines) };
    memcpy(buf, &h, sizeof h);
    return sizeof h;   /* the line bodies are encoded explicitly afterwards */
}

